    private static func calendarStartOffsetMinutes(from text: String) -> Int? {
        if let duration = RelativeDuration.parse(from: text) {
            return duration.minutesCeiled
        }
        if RelativeDuration.containsExplicitRelativeSyntax(text) {
            return nil
