        for (word, hour) in words where text.contains(" at \(word)") {
            let pm = text.contains("pm") || text.contains("afternoon") || text.contains("evening")
            return pm && hour < 12 ? hour + 12 : hour
        }","language":"swift","lineEnd":640,"lineStart":596,"module":"Services","path":"ios/Lumen/Services/DeterministicToolPlanner.swift","sourceHash":"cbb36c347333d300a997ae69fc058fdefb0b778ff141d6c1a25d7df284bb9efa"}

