        if matchesAny(text, ["re-call"]) { return false }

        let directCallPatterns = [
            #"\bcall\s+(me|him|her|them|us|[a-z0-9@+\-().]+)\b"#,
            #"\bdial\s+"#,
            #"\bphone\s+"#,
            #"\bstart\s+a?\s*call\b"#
        ]
        return directCallPatterns.contains { pattern in
            text.range(of: pattern, options: .regularExpression) != nil
        }
    }

