    /// - Parameters:
    ///   - reasoningCaptureEnabled: Determines the directive type in DEBUG builds.","language":"swift","lineEnd":37,"lineStart":1,"module":"Services/LLM","path":"ios/Lumen/Services/LLM/ModelThinkingControl.swift","sourceHash":"3470b5fbeb20b529e251e3c7e2274a9d28f5debf89114f2fc05fa5a1b46476ae"}

