        if let sl { parts.append(String(format: "%.1fh sleep", sl)) }

        if parts.isEmpty {
            return "No Health data available yet today (or access denied). Open the Health app and grant permission."
        }
        return "Today's Health: " + parts.joined(separator: " · ")
    }

