        switch raw?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() {
        case "relative", "once", "one-time", "one time":
            return .once
        case "absolute", "daily":
            return .daily","language":"swift","lineEnd":48,"lineStart":1,"module":"Services/Tools","path":"ios/Lumen/Services/Tools/TriggerTools.swift","sourceHash":"cd3c728377d7f8a980d396d508f8c598505b827843e6a3b2410dcdf9610cb1bb"}

