        case .maintenanceIdle:
            guard !input.lowPowerMode else {
                return ComputeDecision(maxTokens: 512, allowHeavyRuntime: false, budgetPolicy: budgetPolicy, denialReason: "\(budgetPolicy.rawValue): lowPowerMode=true")
