            ResourceBudgetGate.recordScenePhase(.active)
            DeferredMaintenanceQueue.shared.updateScenePhase(.active)","language":"swift","lineEnd":57,"lineStart":1,"module":"System","path":"ios/Lumen/System/SceneTransitionCoordinator.swift","sourceHash":"2a2d961b2003351ea79594f5804db5507a1b3c9c243152b4b06990fc552462e1"}

