        XCTAssertTrue(decodeFailure.diagnostic?.hasPrefix("rtf_decode_failed:") == true)
        XCTAssertFalse(decodeFailure.diagnostic?.contains(rawPath) == true)
        XCTAssertNotEqual(readFailure.diagnostic, decodeFailure.diagnostic)
    }

