    if client_id != EXPECTED_CLIENT_ID:
        fail(f"MSALClientID mismatch. Expected {EXPECTED_CLIENT_ID}, found {client_id}")

    redirect_uri = (config.get("MSALRedirectURI") or "").strip()
    if not redirect_uri:
