        _CURRENT_RECOMMENDATION_RE,
        _SECURITY_RE,
        _MODEL_IDENTITY_RE,
        _COPYRIGHT_STYLE_RE,
        _UNSAFE_EDIT_RE,
        _CORPUS_ARTIFACT_RE,
    )
    return any(pattern.search(value) for value in values for pattern in patterns)


